<?php require __DIR__.'/../../../app/core/bootstrap.php';header('Content-Type: application/json');$d=[];$d['total_books']=(int)$pdo->query("SELECT COUNT(*) FROM books WHERE approval_status='disetujui'")->fetchColumn();$d['active_users']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE status='aktif' AND role_id=(SELECT id FROM roles WHERE name='pengguna')")->fetchColumn();$d['public_repository']=(int)$pdo->query("SELECT COUNT(*) FROM repositories WHERE status='publik' AND type='skripsi'")->fetchColumn();$d['pending_submissions']=(int)$pdo->query("SELECT (SELECT COUNT(*) FROM books WHERE approval_status<>'disetujui')+(SELECT COUNT(*) FROM repositories WHERE type='skripsi' AND status<>'publik')")->fetchColumn();echo json_encode($d);
